const body = $input.first().json.body || $input.first().json || {};
const messageText = body.messageText || body.message || '';
const senderPhone = body.senderPhone || body.phone || 'Unknown';
const senderName = body.senderName || body.name || 'Valued Patient';

// 1. Name Extraction / Sanitization
let patientName = senderName;
const nameMatch = messageText.match(/(?:my name is|i am|this is|call me)\s+([a-zA-Z\s]{2,25})/i);
if (nameMatch && nameMatch[1]) {
  patientName = nameMatch[1].trim();
}

// 2. Emergency & Pain Detection
const isEmergency = /pain|emergency|bleeding|swelling|broken|ache|severe|trauma|urgent|infection|fell|cracked/i.test(messageText);

// 3. Service / Reason
let service = 'General Consultation / Dental Checkup';
if (isEmergency) {
  service = 'Emergency Toothache / Acute Dental Care';
} else if (/clean|whitening|hygiene|scale/i.test(messageText)) {
  service = 'Routine Cleaning & Preventative Care';
} else if (/filling|cavity|crown|implant/i.test(messageText)) {
  service = 'Restorative Dentistry / Filling & Crown';
} else if (/brace|aligner|invisalign/i.test(messageText)) {
  service = 'Orthodontics & Teeth Alignment';
}

// 4. Preferred Time / Scheduling
let preferredTime = 'Earliest Available Slot';
if (/today|urgent|now|asap/i.test(messageText)) {
  preferredTime = 'Today (Immediate Walk-In / Triage)';
} else if (/tomorrow/i.test(messageText)) {
  preferredTime = 'Tomorrow';
} else if (/morning/i.test(messageText)) {
  preferredTime = 'Morning Slot';
} else if (/afternoon/i.test(messageText)) {
  preferredTime = 'Afternoon Slot';
}

// 5. Triage Status & Notes
const triageStatus = isEmergency ? 'HIGH PRIORITY / EMERGENCY (WHATSAPP RECOVERY)' : 'STANDARD / ROUTINE (WHATSAPP RECOVERY)';
const notes = isEmergency 
  ? `Sub-60s Auto-Recovery: Patient reported urgent symptoms: "${messageText.slice(0, 100)}..."` 
  : `Sub-60s Auto-Recovery: WhatsApp inquiry for ${service}.`;

// 6. Safe Phone formatting for Google Sheets
const safePhone = String(senderPhone).startsWith('+') ? `'${senderPhone}` : String(senderPhone);

// 7. Formulate AI Auto-TextBack Message
let autoReply = '';
if (isEmergency) {
  autoReply = `Hi ${patientName}! This is Sarah from Apex Dental Clinic. I see we missed your call — so sorry about that! I noticed you are dealing with urgent dental pain. Our clinical triage has flagged this as HIGH PRIORITY. Our on-duty dentist is being alerted now, or you can walk in immediately to our emergency clinic at 123 Healthcare Blvd. We're here to help!`;
} else {
  autoReply = `Hi ${patientName}! This is Sarah from Apex Dental Clinic. We noticed we just missed your call — sorry for the inconvenience! We'd love to help you get booked for ${service}. We have openings available this week. Would morning or afternoon suit you best?`;
}

return {
  json: {
    'TIMESTAMP': new Date().toLocaleString(),
    'PATIENT NAME': patientName,
    'PHONE NUMBER': safePhone,
    'SERVICE / REASON': service,
    'PREFERRED TIME': preferredTime,
    'TRIAGE STATUS': triageStatus,
    'NOTES': notes,
    'reply': autoReply
  }
};

const item = $input.first().json;
return {
  json: {
    'TIMESTAMP': item['TIMESTAMP'],
    'PATIENT NAME': item['PATIENT NAME'],
    'PHONE NUMBER': item['PHONE NUMBER'],
    'SERVICE / REASON': item['SERVICE / REASON'],
    'PREFERRED TIME': item['PREFERRED TIME'],
    'TRIAGE STATUS': item['TRIAGE STATUS'],
    'NOTES': item['NOTES']
  }
};
